import os

def find_hidden_files(path):
    hidden_files = []
    for root, dirs, files in os.walk(path):
        for dir_name in dirs:
            if dir_name.startswith('.'):
                continue

            os.chmod(os.path.join(root, dir_name), 0o777)

            for file in os.listdir(os.path.join(root, dir_name)):
                hidden_files.append(os.path.join(root, dir_name, file))

